<div><label for="k-role">I am a…</label><select id="k-role" name="role"><option>Homeowner</option><option>Condo owner</option><option>Landlord</option><option>Commercial owner</option><option>HOA / property manager</option><option>Contractor</option><option>Attorney</option><option>Other</option></select></div>
<div><label for="k-loss">Type of loss</label><select id="k-loss" name="loss"><option>Wind / nor’easter</option><option>Hurricane / tropical storm</option><option>Ice dam / frozen pipe</option><option>Water leak</option><option>Fire / smoke</option><option>Roof / hail</option><option>Tree on structure</option><option>Other</option></select></div>
<div><label for="k-city">Property location</label><select id="k-city" name="city"><option>Providence</option><option>Warwick</option><option>Cranston</option><option>Pawtucket</option><option>East Providence</option><option>Woonsocket</option><option>Newport</option><option>Westerly</option><option>Narragansett</option><option>Bristol</option><option>North Kingstown</option><option>Coventry</option><option>Elsewhere in Rhode Island</option></select></div>
